_CMP_OPS = ("=", "!=", "<", "<=", ">", ">="


class _Group:
    __slots__ = ("row_count", "counts", "sums", "mins", "maxs", "distinct")

    def __init__(self, n_cols, distinct_needed, any_sum, any_min, any_max, any_distinct):
        self.row_count = 0
        self.counts = [0] * n_cols
        self.sums = [0] * n_cols if any_sum else None
        self.mins = [None] * n_cols if any_min else None
        self.maxs = [None] * n_cols if any_max else None
        self.distinct = [set() if d else None for d in distinct_needed] if any_distinct else None


def _compile_condition(cond):
    t = cond[0]

    if t == "and":
        return ("and", _compile_condition(cond[1]), _compile_condition(cond[2]))
    if t == "or":
        return ("or", _compile_condition(cond[1]), _compile_condition(cond[2]))
    if t == "not":
        return ("not", _compile_condition(cond[1]))
    if t == "is_null":
        return ("is_null", tuple(cond[1]))
    if t == "in":
        x = tuple(cond[1])
        elems = cond[2]
        if not elems:
            return ("in", x, frozenset(), False, True)
        has_null = False
        non_null = []
        for e in elems:
            if e is None:
                has_null = True
            else:
                non_null.append(e)
        return ("in", x, frozenset(non_null), has_null, False)
    if t == "between":
        return ("between", tuple(cond[1]), cond[2], cond[3])

    return ("cmp", t, tuple(cond[1]), tuple(cond[2]))


def _eval_where(node, row):
    typ = node[0]

    if typ == "cmp":
        op = node[1]
        xop = node[2]
        yop = node[3]

        x = row[xop[1]] if xop[0] == "col" else xop[1]
        y = row[yop[1]] if yop[0] == "col" else yop[1]

        if x is None or y is None:
            return None

        if op == "=":
            return x == y
        if op == "!=":
            return x != y
        if op == "<":
            return x < y
        if op == "<=":
            return x <= y
        if op == ">":
            return x > y
        return x >= y

    if typ == "and":
        left = _eval_where(node[1], row)
        if left is False:
            return False
        right = _eval_where(node[2], row)
        if right is False:
            return False
        if left is None or right is None:
            return None
        return True

    if typ == "or":
        left = _eval_where(node[1], row)
        if left is True:
            return True
        right = _eval_where(node[2], row)
        if right is True:
            return True
        if left is None or right is None:
            return None
        return False

    if typ == "not":
        v = _eval_where(node[1], row)
        if v is None:
            return None
        return not v

    if typ == "is_null":
        op = node[1]
        v = row[op[1]] if op[0] == "col" else op[1]
        return v is None

    if typ == "in":
        xop = node[1]
        x = row[xop[1]] if xop[0] == "col" else xop[1]
        if node[4]:
            return False
        if x is None:
            return None
        if x in node[2]:
            return True
        return None if node[3] else False

    # between
    xop = node[1]
    x = row[xop[1]] if xop[0] == "col" else xop[1]
    if x is None:
        return None

    lo = node[2]
    hi = node[3]

    left = None if lo is None else (x >= lo)
    right = None if hi is None else (x <= hi)

    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _get_having_operand(op, group_values, group_index, agg_values):
    t = op[0]
    if t == "col":
        return group_values[group_index[op[1]]]
    if t == "val":
        return op[1]
    return agg_values[(op[1], op[2])]


def _eval_having(node, group_values, group_index, agg_values):
    typ = node[0]

    if typ == "cmp":
        op = node[1]
        x = _get_having_operand(node[2], group_values, group_index, agg_values)
        y = _get_having_operand(node[3], group_values, group_index, agg_values)

        if x is None or y is None:
            return None

        if op == "=":
            return x == y
        if op == "!=":
            return x != y
        if op == "<":
            return x < y
        if op == "<=":
            return x <= y
        if op == ">":
            return x > y
        return x >= y

    if typ == "and":
        left = _eval_having(node[1], group_values, group_index, agg_values)
        if left is False:
            return False
        right = _eval_having(node[2], group_values, group_index, agg_values)
        if right is False:
            return False
        if left is None or right is None:
            return None
        return True

    if typ == "or":
        left = _eval_having(node[1], group_values, group_index, agg_values)
        if left is True:
            return True
        right = _eval_having(node[2], group_values, group_index, agg_values)
        if right is True:
            return True
        if left is None or right is None:
            return None
        return False

    if typ == "not":
        v = _eval_having(node[1], group_values, group_index, agg_values)
        if v is None:
            return None
        return not v

    if typ == "is_null":
        v = _get_having_operand(node[1], group_values, group_index, agg_values)
        return v is None

    if typ == "in":
        x = _get_having_operand(node[1], group_values, group_index, agg_values)
        if node[4]:
            return False
        if x is None:
            return None
        if x in node[2]:
            return True
        return None if node[3] else False

    # between
    x = _get_having_operand(node[1], group_values, group_index, agg_values)
    if x is None:
        return None

    lo = node[2]
    hi = node[3]

    left = None if lo is None else (x >= lo)
    right = None if hi is None else (x <= hi)

    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _collect_agg_specs(cond, specs):
    t = cond[0]

    if t == "and" or t == "or":
        _collect_agg_specs(cond[1], specs)
        _collect_agg_specs(cond[2], specs)
    elif t == "not":
        _collect_agg_specs(cond[1], specs)
    elif t in _CMP_OPS:
        for op in (cond[1], cond[2]):
            if op[0] == "agg":
                specs.add((op[1], op[2]))
    elif t == "is_null":
        op = cond[1]
        if op[0] == "agg":
            specs.add((op[1], op[2]))
    elif t == "in":
        op = cond[1]
        if op[0] == "agg":
            specs.add((op[1], op[2]))
    elif t == "between":
        op = cond[1]
        if op[0] == "agg":
            specs.add((op[1], op[2]))


def run_query(rows: list[dict], query: dict) -> list[dict]:
    select = query["select"]

    select_descs = []
    select_cols = []
    for item in select:
        if isinstance(item, str):
            select_descs.append(("col", item, None))
            select_cols.append(item)
        else:
            func, arg = item
            select_descs.append(("agg", f"{func}({arg})", (func, arg)))

    has_aggregates = any(kind == "agg" for kind, _, _ in select_descs)

    where = query.get("where")
    wnode = _compile_condition(where) if where is not None else None
    eval_where = _eval_where

    having = query.get("having")
    hnode = _compile_condition(having) if having is not None else None
    eval_having = _eval_having

    group_by = query.get("group_by")
    group_cols = list(group_by) if group_by else []
    group_index = {c: i for i, c in enumerate(group_cols)}

    specs = set()
    for kind, _, agg_key in select_descs:
        if kind == "agg":
            specs.add(agg_key)
    if having is not None:
        _collect_agg_specs(having, specs)

    unique_specs = list(specs)

    needed_cols = []
    col_index = {}
    for func, arg in unique_specs:
        if arg != "*" and arg not in col_index:
            col_index[arg] = len(needed_cols)
            needed_cols.append(arg)

    n_cols = len(needed_cols)

    sum_needed = [False] * n_cols
    min_needed = [False] * n_cols
    max_needed = [False] * n_cols
    distinct_needed = [False] * n_cols

    for func, arg in unique_specs:
        if arg == "*":
            continue
        i = col_index[arg]
        if func == "sum" or func == "avg":
            sum_needed[i] = True
        elif func == "min":
            min_needed[i] = True
        elif func == "max":
            max_needed[i] = True
        elif func == "count_distinct":
            distinct_needed[i] = True

    any_sum = any(sum_needed)
    any_min = any(min_needed)
    any_max = any(max_needed)
    any_distinct = any(distinct_needed)

    def add_state(state, row):
        state.row_count += 1
        if n_cols == 0:
            return

        counts = state.counts
        sums = state.sums
        mins = state.mins
        maxs = state.maxs
        distinct = state.distinct

        for i, col in enumerate(needed_cols):
            v = row[col]
            if v is not None:
                counts[i] += 1
                if sum_needed[i]:
                    sums[i] += v
                if min_needed[i]:
                    cur = mins[i]
                    if cur is None or v < cur:
                        mins[i] = v
                if max_needed[i]:
                    cur = maxs[i]
                    if cur is None or v > cur:
                        maxs[i] = v
                if distinct_needed[i]:
                    distinct[i].add(v)

    def compute_aggregates(state):
        values = {}
        for func, arg in unique_specs:
            if arg == "*":
                values[(func, arg)] = state.row_count
                continue

            i = col_index[arg]
            c = state.counts[i]

            if func == "count":
                values[(func, arg)] = c
            elif func == "count_distinct":
                values[(func, arg)] = len(state.distinct[i])
            elif func == "sum":
                values[(func, arg)] = state.sums[i] if c else None
            elif func == "min":
                values[(func, arg)] = state.mins[i]
            elif func == "max":
                values[(func, arg)] = state.maxs[i]
            else:  # avg
                values[(func, arg)] = state.sums[i] // c if c else None

        return values

    def make_agg_row(group_values, agg_values):
        out_row = {}
        for kind, name, agg_key in select_descs:
            if kind == "col":
                out_row[name] = group_values[group_index[name]]
            else:
                out_row[name] = agg_values[agg_key]
        return out_row

    output = []

    if has_aggregates:
        if group_cols:
            groups = {}

            if len(group_cols) == 1:
                c0 = group_cols[0]
                if wnode is None:
                    for row in rows:
                        key = (row[c0],)
                        state = groups.get(key)
                        if state is None:
                            state = _Group(n_cols, distinct_needed, any_sum, any_min, any_max, any_distinct)
                            groups[key] = state
                        add_state(state, row)
                else:
                    for row in rows:
                        if eval_where(wnode, row) is True:
                            key = (row[c0],)
                            state = groups.get(key)
                            if state is None:
                                state = _Group(n_cols, distinct_needed, any_sum, any_min, any_max, any_distinct)
                                groups[key] = state
                            add_state(state, row)
            else:
                if wnode is None:
                    for row in rows:
                        key = tuple(row[c] for c in group_cols)
                        state = groups.get(key)
                        if state is None:
                            state = _Group(n_cols, distinct_needed, any_sum, any_min, any_max, any_distinct)
                            groups[key] = state
                        add_state(state, row)
                else:
                    for row in rows:
                        if eval_where(wnode, row) is True:
                            key = tuple(row[c] for c in group_cols)
                            state = groups.get(key)
                            if state is None:
                                state = _Group(n_cols, distinct_needed, any_sum, any_min, any_max, any_distinct)
                                groups[key] = state
                            add_state(state, row)

            for key, state in groups.items():
                agg_values = compute_aggregates(state)
                if hnode is not None and eval_having(hnode, key, group_index, agg_values) is not True:
                    continue
                output.append(make_agg_row(key, agg_values))

        else:
            state = _Group(n_cols, distinct_needed, any_sum, any_min, any_max, any_distinct)
            if wnode is None:
                for row in rows:
                    add_state(state, row)
            else:
                for row in rows:
                    if eval_where(wnode, row) is True:
                        add_state(state, row)

            agg_values = compute_aggregates(state)
            if hnode is None or eval_having(hnode, (), {}, agg_values) is True:
                output.append(make_agg_row((), agg_values))

    else:
        if group_cols:
            groups = {}

            if len(group_cols) == 1:
                c0 = group_cols[0]
                if wnode is None:
                    for row in rows:
                        groups.setdefault((row[c0],), None)
                else:
                    for row in rows:
                        if eval_where(wnode, row) is True:
                            groups.setdefault((row[c0],), None)
            else:
                if wnode is None:
                    for row in rows:
                        groups.setdefault(tuple(row[c] for c in group_cols), None)
                else:
                    for row in rows:
                        if eval_where(wnode, row) is True:
                            groups.setdefault(tuple(row[c] for c in group_cols), None)

            select_indices = [(name, group_index[name]) for name in select_cols]
            for key in groups:
                out_row = {}
                for name, idx in select_indices:
                    out_row[name] = key[idx]
                output.append(out_row)

        else:
            if not select_cols:
                if wnode is None:
                    output = [{} for row in rows]
                else:
                    output = [{} for row in rows if eval_where(wnode, row) is True]
            elif len(select_cols) == 1:
                c0 = select_cols[0]
                if wnode is None:
                    output = [{c0: row[c0]} for row in rows]
                else:
                    output = [{c0: row[c0]} for row in rows if eval_where(wnode, row) is True]
            else:
                if wnode is None:
                    output = [{name: row[name] for name in select_cols} for row in rows]
                else:
                    output = [{name: row[name] for name in select_cols} for row in rows if eval_where(wnode, row) is True]

    if query.get("distinct"):
        seen = set()
        dedup = []
        if select_descs:
            for out_row in output:
                key = tuple(out_row.values())
                if key not in seen:
                    seen.add(key)
                    dedup.append(out_row)
        elif output:
            dedup.append(output[0])
        output = dedup

    order_by = query.get("order_by")
    if order_by:
        for key, direction, nulls in reversed(order_by):
            desc = direction == "desc"

            if desc:
                none_rank = 1 if nulls == "first" else 0
            else:
                none_rank = 1 if nulls == "last" else 0

            nonnull_rank = 1 - none_rank

            output = sorted(
                output,
                key=lambda r, k=key, nr=none_rank, nnr=nonnull_rank: (nr if r[k] is None else nnr, r[k]),
                reverse=desc,
            )

    offset = query.get("offset")
    if offset:
        output = output[offset:]

    limit = query.get("limit")
    if limit is not None:
        output = output[:limit]

    return output
